script:
(function () {
  'use strict';
  // Date arithmetic on whole day numbers (days since 1970-01-01 in the proleptic Gregorian
  // calendar, H. Hinnant's days_from_civil / civil_from_days). No Date objects or time zones are
  // involved after reading "today", so daylight saving time can never shift a result by a day.
  //   Days between = end - start (+1 when the end date is included).
  //   Years/months/days: the most whole months that fit (month ends clamp: Jan 31 + 1 month =
  //   Feb 28/29), then the leftover days.
  //   Adding: years and months first (clamped), then weeks x 7 + days; subtracting negates all.
  //   Business days skip Saturdays, Sundays and, optionally, US federal holidays (5 U.S.C. 6103)
  //   on their observed dates: a Saturday holiday is observed the Friday before (so New Year's Day
  //   on a Saturday is observed Dec 31), a Sunday holiday the Monday after. Juneteenth counts from
  //   2021, Martin Luther King Jr. Day from 1986, Veterans Day is the 4th Monday of October in
  //   1971-1977; holidays are only applied from 1971 (the Monday Holiday Act) onward.
  // Verified (Node scratch test): 2024-01-01 -> 2024-12-31 = 365 days (366 with end date);
  // 2000-02-28 -> 2000-03-01 = 2 days; 1970-01-01 is a Thursday, 2026-10-01 a Thursday;
  // 2024-01-31 + 1 month = 2024-02-29; 2023-01-31 + 1 month = 2023-02-28; 2024-02-29 + 1 year =
  // 2025-02-28; 2024-03-10 + 1 day = 2024-03-11 (US DST start); weekdays 2026-01-05 (Mon) ->
  // 2026-01-12 (Mon) = 5; observed holidays 2021: Dec 31 2021 (NY 2022 on Sat), Jun 18 2021,
  // Jul 5 2021, Dec 24 2021; the 2026 and 2027 observed dates match OPM's published federal
  // holiday lists (opm.gov, checked 2026-10-01); 2026 has 261 weekdays and 250 business days.
  // Date conversion matches Date.UTC for every 997th day from 0001-01-01 to 9999-12-31.
  var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  var DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  var intf = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });

  function daysFromCivil(y, m, d) {
    y -= m <= 2 ? 1 : 0;
    var era = Math.floor(y / 400), yoe = y - era * 400;
    var doy = Math.floor((153 * ((m + 9) % 12) + 2) / 5) + d - 1;
    var doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
    return era * 146097 + doe - 719468;
  }
  function civilFromDays(z) {
    z += 719468;
    var era = Math.floor(z / 146097), doe = z - era * 146097;
    var yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
    var doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
    var mp = Math.floor((5 * doy + 2) / 153);
    var d = doy - Math.floor((153 * mp + 2) / 5) + 1, m = mp < 10 ? mp + 3 : mp - 9;
    return { y: yoe + era * 400 + (m <= 2 ? 1 : 0), m: m, d: d };
  }
  function isLeap(y) { return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0; }
  function daysInMonth(y, m) { return m === 2 ? (isLeap(y) ? 29 : 28) : [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1]; }
  function weekday(z) { return (((z + 4) % 7) + 7) % 7; } // 0 = Sunday; day 0 (1970-01-01) = Thursday

  function parseISO(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s || ''));
    if (!m) return null;
    var y = +m[1], mo = +m[2], d = +m[3];
    if (y < 1 || mo < 1 || mo > 12 || d < 1 || d > daysInMonth(y, mo)) return null;
    return daysFromCivil(y, mo, d);
  }
  function pad(n, w) { var s = String(n); while (s.length < w) s = '0' + s; return s; }
  function toISO(z) { var c = civilFromDays(z); return pad(c.y, 4) + '-' + pad(c.m, 2) + '-' + pad(c.d, 2); }
  function longDate(z) { var c = civilFromDays(z); return DAYS[weekday(z)] + ', ' + MONTHS[c.m - 1] + ' ' + c.d + ', ' + c.y; }
  function shortDate(z) { var c = civilFromDays(z); return DAYS[weekday(z)].slice(0, 3) + ', ' + MONTHS[c.m - 1].slice(0, 3) + ' ' + c.d + ', ' + c.y; }

  // Adds whole months, clamping the day to the target month's length.
  function addMonths(z, months) {
    var c = civilFromDays(z);
    var total = c.y * 12 + (c.m - 1) + months;
    var y = Math.floor(total / 12), m = total - y * 12 + 1;
    return daysFromCivil(y, m, Math.min(c.d, daysInMonth(y, m)));
  }
  // Years, months and days from a to b (a <= b).
  function ymd(a, b) {
    var A = civilFromDays(a), B = civilFromDays(b);
    var months = (B.y - A.y) * 12 + (B.m - A.m);
    if (addMonths(a, months) > b) months--;
    return { years: Math.floor(months / 12), months: months % 12, days: b - addMonths(a, months) };
  }

  // ---- US federal holidays (5 U.S.C. 6103), observed dates ----
  function nthWeekday(y, m, wd, n) { var f = daysFromCivil(y, m, 1); return f + (wd - weekday(f) + 7) % 7 + (n - 1) * 7; }
  function lastWeekday(y, m, wd) { var l = daysFromCivil(y, m, daysInMonth(y, m)); return l - (weekday(l) - wd + 7) % 7; }
  function observed(z) { var w = weekday(z); return w === 6 ? z - 1 : w === 0 ? z + 1 : z; }
  function holidaysOfYear(y) {
    if (y < 1971) return [];
    var h = [
      [observed(daysFromCivil(y, 1, 1)), 'New Year’s Day'],
      [nthWeekday(y, 2, 1, 3), 'Washington’s Birthday (Presidents Day)'],
      [lastWeekday(y, 5, 1), 'Memorial Day'],
      [observed(daysFromCivil(y, 7, 4)), 'Independence Day'],
      [nthWeekday(y, 9, 1, 1), 'Labor Day'],
      [nthWeekday(y, 10, 1, 2), 'Columbus Day'],
      [y <= 1977 ? nthWeekday(y, 10, 1, 4) : observed(daysFromCivil(y, 11, 11)), 'Veterans Day'],
      [nthWeekday(y, 11, 4, 4), 'Thanksgiving Day'],
      [observed(daysFromCivil(y, 12, 25)), 'Christmas Day']
    ];
    if (y >= 1986) h.push([nthWeekday(y, 1, 1, 3), 'Martin Luther King Jr. Day']);
    if (y >= 2021) h.push([observed(daysFromCivil(y, 6, 19)), 'Juneteenth National Independence Day']);
    return h.sort(function (p, q) { return p[0] - q[0]; });
  }
  var holidayCache = {};
  function holidayMap(y) {
    if (!holidayCache[y]) {
      var map = {};
      holidaysOfYear(y).forEach(function (h) { map[h[0]] = h[1]; });
      holidayCache[y] = map;
    }
    return holidayCache[y];
  }
  // Name of the observed holiday on day z, or ''. (New Year's Day can be observed on Dec 31.)
  function holidayOn(z) {
    var y = civilFromDays(z).y;
    return holidayMap(y)[z] || holidayMap(y + 1)[z] || '';
  }
  function isBusinessDay(z, useHolidays) {
    var w = weekday(z);
    if (w === 0 || w === 6) return false;
    return !(useHolidays && holidayOn(z));
  }
  // Weekdays in [a, b).
  function weekdaysBetween(a, b) {
    var n = b - a, full = Math.floor(n / 7), count = full * 5;
    for (var z = a + full * 7; z < b; z++) { var w = weekday(z); if (w !== 0 && w !== 6) count++; }
    return count;
  }
  // Observed federal holidays in [a, b), each [day, name].
  function holidaysBetween(a, b) {
    var out = [], seen = {};
    var y0 = civilFromDays(a).y, y1 = civilFromDays(b).y;
    for (var y = y0; y <= y1 + 1; y++) {
      holidaysOfYear(y).forEach(function (h) {
        if (h[0] >= a && h[0] < b && !seen[h[0]]) { seen[h[0]] = true; out.push(h); }
      });
    }
    return out.sort(function (p, q) { return p[0] - q[0]; });
  }
  // Steps n business days forward (dir 1) or back (dir -1).
  function addBusinessDays(z, n, dir, useHolidays) {
    var count = 0;
    while (count < n) { z += dir; if (isBusinessDay(z, useHolidays)) count++; }
    return z;
  }

  function plural(n, word) { return intf.format(n) + ' ' + word + (n === 1 ? '' : 's'); }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function el(id) { return document.getElementById(id); }
  function num(id) {
    var s = String(el(id).value).trim();
    if (s === '') return 0;
    var v = Number(s);
    return isFinite(v) ? v : NaN;
  }
  var MIN_DAY = daysFromCivil(1, 1, 1), MAX_DAY = daysFromCivil(9999, 12, 31);

  function updateBetween() {
    var a = parseISO(el('dtStart').value), b = parseISO(el('dtEnd').value);
    var inclusive = el('dtInclusive').checked, useHol = el('dtHolidays').checked;
    var error = el('dtBetweenError');
    var bad = a === null || b === null;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Choose a valid start and end date (years 0001 to 9999).';
      ['dtTotal', 'dtYmd', 'dtWeeks', 'dtBusiness', 'dtHours'].forEach(function (id) { set(id, '–'); });
      set('dtDirection', '');
      el('dtHolidayList').hidden = true;
      return;
    }
    var lo = Math.min(a, b), hi = Math.max(a, b) + (inclusive ? 1 : 0);
    var total = hi - lo;
    var p = ymd(lo, hi);
    set('dtTotal', plural(total, 'day'));
    set('dtYmd', [plural(p.years, 'year'), plural(p.months, 'month'), plural(p.days, 'day')].join(', '));
    set('dtWeeks', plural(Math.floor(total / 7), 'week') + ', ' + plural(total % 7, 'day'));
    set('dtHours', intf.format(total * 24) + ' hours');
    var hols = useHol ? holidaysBetween(lo, hi) : [];
    var business = weekdaysBetween(lo, hi) - hols.length; // observed holidays always fall on weekdays
    set('dtBusinessLabel', useHol ? 'Business days (no weekends or federal holidays)' : 'Weekdays (Monday to Friday)');
    set('dtBusiness', plural(business, 'day'));
    set('dtDirection', a === b && !inclusive ? 'The two dates are the same.' :
      (b < a ? 'The end date is before the start date, so the count runs from the earlier date to the later one. ' : '') +
      (inclusive ? 'Both dates are counted.' : 'The earlier date is counted and the later date is not.'));
    var list = el('dtHolidayList');
    list.hidden = !useHol;
    if (useHol) {
      set('dtHolidayCount', hols.length === 0 ? 'No federal holidays fall on a weekday in this range.' :
        plural(hols.length, 'federal holiday') + ' excluded' + (hols.length > 40 ? ' (first 40 listed).' : '.'));
      el('dtHolidayRows').innerHTML = hols.slice(0, 40).map(function (h) {
        return '<tr><td>' + shortDate(h[0]) + '</td><td>' + h[1] + '</td></tr>';
      }).join('');
      el('dtHolidayTable').hidden = hols.length === 0;
      el('dtPre1971').hidden = civilFromDays(lo).y >= 1971;
    }
  }

  function updateAdd() {
    var start = parseISO(el('dtFrom').value);
    var dir = el('dtOp').value === 'sub' ? -1 : 1;
    var years = num('dtYears'), months = num('dtMonths'), weeks = num('dtWeeksIn'), days = num('dtDays');
    var bizMode = el('dtBizMode').checked, useHol = el('dtBizHolidays').checked;
    el('dtBizHolidaysWrap').hidden = !bizMode;
    set('dtDaysLabel', bizMode ? 'Business days' : 'Days');
    var error = el('dtAddError');
    var vals = [years, months, weeks, days];
    var bad = start === null || vals.some(function (v) { return isNaN(v) || v < 0 || Math.floor(v) !== v; }) ||
              years > 9999 || months > 120000 || weeks > 600000 || days > (bizMode ? 100000 : 4000000);
    var msg = bad ? 'Choose a valid date and enter whole, non-negative numbers (up to 100,000 business days).' : '';
    var result = null;
    if (!bad) {
      var z = addMonths(start, dir * (years * 12 + months));
      z += dir * weeks * 7;
      if (z < MIN_DAY || z > MAX_DAY) { msg = 'The result falls outside the years 0001 to 9999.'; }
      else {
        z = bizMode ? addBusinessDays(z, days, dir, useHol) : z + dir * days;
        if (z < MIN_DAY || z > MAX_DAY) msg = 'The result falls outside the years 0001 to 9999.';
        else result = z;
      }
    }
    error.hidden = !msg;
    error.textContent = msg;
    if (result === null) {
      ['dtResult', 'dtResultIso', 'dtResultSpan'].forEach(function (id) { set(id, '–'); });
      set('dtResultNote', '');
      return;
    }
    set('dtResult', longDate(result));
    set('dtResultIso', toISO(result));
    var span = Math.abs(result - start);
    set('dtResultSpan', plural(span, 'calendar day') + (result >= start ? ' after ' : ' before ') + 'the start date');
    var c0 = civilFromDays(start), notes = [];
    if ((years || months) && c0.d > 28 && civilFromDays(addMonths(start, dir * (years * 12 + months))).d !== c0.d) {
      notes.push('The target month is shorter than day ' + c0.d + ', so the date moves to that month’s last day.');
    }
    if (bizMode && useHol && civilFromDays(Math.min(start, result)).y < 1971) {
      notes.push('Federal holidays are only skipped from 1971 onward.');
    }
    var h = holidayOn(result);
    if (h) notes.push('This date is a federal holiday (' + h + ', observed).');
    else if (weekday(result) === 0 || weekday(result) === 6) notes.push('This date falls on a weekend.');
    set('dtResultNote', notes.join(' '));
  }

  function todayDay() { var t = new Date(); return daysFromCivil(t.getFullYear(), t.getMonth() + 1, t.getDate()); }

  document.addEventListener('DOMContentLoaded', function () {
    var today = todayDay(), c = civilFromDays(today);
    if (!el('dtStart').value) el('dtStart').value = toISO(today);
    if (!el('dtEnd').value) el('dtEnd').value = toISO(daysFromCivil(c.y, 12, 31));
    if (!el('dtFrom').value) el('dtFrom').value = toISO(today);
    [['dtBetweenForm', updateBetween], ['dtAddForm', updateAdd]].forEach(function (pair) {
      var form = el(pair[0]);
      form.addEventListener('input', pair[1]);
      form.addEventListener('change', pair[1]);
      form.addEventListener('submit', function (e) { e.preventDefault(); });
      pair[1]();
    });
  });
})();
